tools.example:
foreach g [get_generated_clocks] {
  puts "$g <- [get_property MASTER_CLOCK $g] period [get_property PERIOD $g]"
}

get_tiles -of_objects [get_sites SLICE_X10Y20]
llength [get_tiles -filter {TILE_TYPE == INT}]
get_tiles -of_objects [get_clock_regions X0Y0] -filter {TYPE =~ BRAM*}

foreach c [get_cells -hier -filter {PRIMITIVE_TYPE =~ *GT*CHANNEL*}] {
  puts "$c on [get_slrs -of_objects $c]"
}
resize_pblock pb_slr2 -add [get_slrs SLR2]

foreach b [get_iobanks -filter {BANK_TYPE == BT_HIGH_PERFORMANCE}] {
  puts "HP bank $b: [llength [get_ports -of_objects $b]] ports"
}
set_property INTERNAL_VREF 0.9 [get_iobanks -of_objects [get_ports {ddr4_dq[*]}]]

get_io_standards -filter {IS_DIFFERENTIAL && VCCO == 1.8}
report_property [get_io_standards LVDS]
get_io_standards -of_objects [get_iobanks 66]

# default delays for everything, then override the critical interfaces
set_input_delay  -clock sys_clk 2.0 [all_inputs]
set_output_delay -clock sys_clk 1.0 [all_outputs]
set_false_path -from [get_ports {btn[*]}]
# ports without a package pin
foreach p [concat [all_inputs] [all_outputs]] {
  if {[get_property PACKAGE_PIN $p] eq ""} { puts "unassigned: $p" }
}

set_clock_uncertainty -setup 0.150 [all_clocks]
foreach c [all_clocks] {
  puts [format "%-30s %6.3f ns" $c [get_property PERIOD $c]]
}

foreach g [get_path_groups] {
  report_timing -group $g -max_paths 1 -file timing_${g}.rpt
}

foreach d [get_net_delays -of_objects [get_nets lane_clk_fwd]] {
  puts "$d slow_max=[get_property SLOW_MAX $d] ps"
}

foreach core [get_debug_cores -filter {NAME != dbg_hub}] {
  puts "$core depth=[get_property C_DATA_DEPTH $core] probes=[llength [get_debug_ports -of_objects $core]]"
}
report_debug_core

report_drc -name drc_impl -ruledecks {default}
set errs [get_drc_violations -name drc_impl -filter {SEVERITY == Error}]
if {[llength $errs]} { error "[llength $errs] DRC errors" }
foreach v [get_methodology_violations -filter {CHECK == TIMING-6}] {
  puts "$v : [get_property DESCRIPTION $v]"
}

foreach d [get_designs] { puts "$d on [get_property PART $d]" }
current_design impl_1
close_design
